using AiVideoEditor.Core.Color;

namespace AiVideoEditor.Core.Interfaces;

/// <summary>
/// Where the 3D LUTs of the HDR → SDR rule live (D033 §3 "LUT"): generated by the application from
/// <see cref="HdrLut.Generate"/> once per key, kept in the application's cache folder. Every decoder of the app uses the
/// same file for the same key, so the Preview, the thumbnails and the export convert alike.
/// </summary>
public interface IHdrLutStore
{
    /// <summary>The full path of the <c>.cube</c> file for <paramref name="conversion"/>'s key (transfer, peak, rule
    /// version), made or verified first. Throws when it can't be made (e.g. the cache folder is not writable).</summary>
    Task<string> GetLutPathAsync(HdrConversion conversion, CancellationToken ct = default);
}
